/**
 * @file test_vs_r_applied.cpp
 * @brief Compare statcpp applied-analysis modules against R 4.4.2 reference values.
 *
 * Covers survival.hpp, time_series.hpp, robust.hpp, multivariate.hpp,
 * categorical.hpp and clustering.hpp. Reference values come from
 * r_reference_applied.hpp, generated by generate_r_reference.R.
 */

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <iterator>
#include <map>
#include <vector>

#include <gtest/gtest.h>

#include "statcpp/categorical.hpp"
#include "statcpp/clustering.hpp"
#include "statcpp/multivariate.hpp"
#include "statcpp/robust.hpp"
#include "statcpp/survival.hpp"
