/// @brief Robust location and scale, outlier fences and winsorising.
TEST(RRobust, LocationScaleAndOutliers) {
    using Case = ref::Robust;
    const auto x = AsVector(Case::kX);
    const auto b = x.begin(), e = x.end();
    // mad is the median absolute deviation with constant 1; mad_scaled applies
    // the 1.4826 factor and equals R's mad().
    EXPECT_R_FIELD(statcpp::mad(b, e), Case, kMad);
    EXPECT_R_FIELD(statcpp::mad_scaled(b, e), Case, kMadScaled);
    EXPECT_R_FIELD(statcpp::mad_scaled(b, e), Case, kMadRCheck);
    EXPECT_R_FIELD(statcpp::hodges_lehmann(b, e), Case, kHodgesLehmann);
    EXPECT_R_FIELD(statcpp::hodges_lehmann(b, e), Case, kHlRCheck);
    EXPECT_R_PVALUE(statcpp::biweight_midvariance(b, e, Case::kC), Case, kBiweightMidvariance);
    EXPECT_R_RANGE(statcpp::winsorize(b, e, Case::kLimits), Case, kWinsorized);

    const auto iqr = statcpp::detect_outliers_iqr(b, e, Case::kK);
    EXPECT_R_FIELD(iqr.q1, Case, kQ1);
    EXPECT_R_FIELD(iqr.q3, Case, kQ3);
    EXPECT_R_FIELD(iqr.iqr_value, Case, kIqrValue);
    EXPECT_R_FIELD(iqr.lower_fence, Case, kLowerFence);
    EXPECT_R_FIELD(iqr.upper_fence, Case, kUpperFence);
    EXPECT_R_FIELD(static_cast<double>(iqr.outliers.size()), Case, kNOutliersIqr);
    EXPECT_R_FIELD(
        static_cast<double>(statcpp::detect_outliers_zscore(b, e, Case::kZThreshold).outliers.size()),
        Case, kNOutliersZ);
    EXPECT_R_FIELD(static_cast<double>(
                       statcpp::detect_outliers_modified_zscore(b, e, Case::kMzThreshold)
                           .outliers.size()),
                   Case, kNOutliersMz);
}

/// @brief Cook's distance and DFFITS against their closed forms.
TEST(RRobust, Influence) {
    using Case = ref::Influence;
    const auto res = AsVector(Case::kResiduals);
    const auto hat = AsVector(Case::kHatValues);
    EXPECT_R_RANGE(statcpp::cooks_distance(res, hat, Case::kMse, Case::kP), Case, kCooks);
    EXPECT_R_RANGE(statcpp::dffits(res, hat, Case::kMse), Case, kDffits);
}

// ============================================================================
// multivariate.hpp
// ============================================================================

/// @brief Normalise an eigenvector so that its largest-magnitude entry is positive.
///
/// The sign of a principal component is arbitrary, so both sides apply the same
/// rule before comparison.
void FixSign(std::vector<double>& v)
{
    std::size_t k = 0;
    for (std::size_t i = 1; i < v.size(); ++i) {
        if (std::abs(v[i]) > std::abs(v[k])) k = i;
    }
    if (v[k] < 0.0) {
        for (double& e : v) e = -e;
    }
}

/// @brief Covariance, correlation, scaling and PCA against cov, cor, scale and prcomp.
TEST(RMultivariate, MatrixOperations) {
    using Case = ref::Multivariate;
    const auto X = MakeMatrix(Case::kXFlat, Case::kXRows, Case::kXCols);
    EXPECT_R_RANGE(Flatten(statcpp::covariance_matrix(X)), Case, kCovarianceMatrix);
    EXPECT_R_RANGE(Flatten(statcpp::correlation_matrix(X)), Case, kCorrelationMatrix);
    EXPECT_R_RANGE(Flatten(statcpp::standardize(X)), Case, kStandardized);
    EXPECT_R_RANGE(Flatten(statcpp::min_max_scale(X)), Case, kMinMaxScaled);

    const auto p = statcpp::pca(X, Case::kNComponents);
    EXPECT_R_PVALUE_RANGE(p.explained_variance, Case, kExplainedVariance);
    EXPECT_R_PVALUE_RANGE(p.explained_variance_ratio, Case, kExplainedVarianceRatio);

    // components is indexed [variable][component], so the sign is normalised per
    // column before flattening in the same row-major order as the reference.
    auto comps = p.components;
    for (std::size_t c = 0; c < Case::kNComponents; ++c) {
        std::vector<double> col;
        for (std::size_t r = 0; r < Case::kXCols; ++r) col.push_back(comps[r][c]);
        FixSign(col);
        for (std::size_t r = 0; r < Case::kXCols; ++r) comps[r][c] = col[r];
    }
    EXPECT_R_PVALUE_RANGE(Flatten(comps), Case, kComponents);

    EXPECT_R_PVALUE(statcpp::power_iteration(statcpp::covariance_matrix(X)).first, Case,
                    kPowerIterationValue);
}

/// @brief Principal component scores against the centred projection.
TEST(RMultivariate, PcaTransform) {
    using Case = ref::PcaTransform;
    const auto X = MakeMatrix(Case::kXFlat, Case::kXRows, Case::kXCols);
    auto p = statcpp::pca(X, Case::kNComponents);
    // Normalise each component's sign before projecting, so the scores match the
    // reference, which was built from the sign-normalised loadings.
    for (std::size_t c = 0; c < Case::kNComponents; ++c) {
        std::vector<double> col;
        for (std::size_t r = 0; r < Case::kXCols; ++r) col.push_back(p.components[r][c]);
        FixSign(col);
        for (std::size_t r = 0; r < Case::kXCols; ++r) p.components[r][c] = col[r];
    }
    const auto scores = statcpp::pca_transform(X, p);
    EXPECT_R_PVALUE_RANGE(Flatten(scores), Case, kScores);
}

